//Color gradient for longer iterations to escape
float ReduceRBGvalue(float IterationEscN) 
{
    return (abs(IterationEscN) - 1.0) * -1.0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //Mapping uv and ScreenRatio
    float ScreenRatio = iResolution.x/iResolution.y;
    vec2 uv = vec2(iResolution.x/ScreenRatio,iResolution.y);

    //Define variables
    vec3 color = vec3(1.0);
    vec2 Z = vec2(fragCoord.x/uv.x,fragCoord.y/uv.y);
    Z *= 2.5;
    Z -= vec2(ScreenRatio*2.2,ScreenRatio*1.5);
    vec2 C = vec2(iMouse.x/300.-1.6,iMouse.y/200.-1.2);//sin(iTime),cos(iTime));
    const int nloop = 1000; //Maximum that my PC could handle stable is 100000
    int Iteration = 0;

    Z += 1.415;
    Z += iMouse.xy/1000. -0.25;

    //Is Pixel part of set
    for (int n = 0; n < nloop; n++) {
        Z = vec2(Z.x * Z.x - Z.y * Z.y, 2.0 * Z.x * Z.y);
        Z = vec2(Z.x + C.x * +1.0, Z.y + C.y * +1.0);
        Iteration += 1;

        //Has Pixel escaped the limit 2.0
        if (length(Z) > 4.0) {
            break;
        }
    }

    //Color grading
    float IterationEscaped = float(Iteration) / float(nloop);
    color = mix(vec3(1.0, 40.0*IterationEscaped, 0.3),
                     vec3(0.0),
                     IterationEscaped);

    // Output to screen
    fragColor = vec4(color,1.0);
}
